package kz.zeroops.api;
import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(name="server_heartbeats") public class ServerHeartbeat { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="server_id",nullable=false) private ManagedServer server; private int cpuPercent; private int ramPercent; private int diskPercent; private int managedContainers; @Column(length=100) private String dockerVersion; @Column(length=100) private String os; @Column(length=100) private String agentVersion; @Column(nullable=false) private Instant createdAt=Instant.now(); protected ServerHeartbeat(){} public ServerHeartbeat(ManagedServer s,int cpu,int ram,int disk,int containers,String docker,String os,String agent){server=s;cpuPercent=cpu;ramPercent=ram;diskPercent=disk;managedContainers=containers;dockerVersion=docker;this.os=os;agentVersion=agent;}}
